svg.script:
//
const CELL=12,MARGIN=10,ORDER=5,FRAMEMS=140,STATEBOUND=1000000;
const B62='0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz';
const ALPHA=" !\"#$%&'()*+,-./0123456789:;<=>?@ABCDEFGHIJKLMNOPQRSTUVWXYZ[\\]^_`abcdefghijklmnopqrstuvwxyz{|}~";
const ABASE=BigInt(ALPHA.length+1);
const PROG=[[3n,2n],[5n,3n],[7n,5n],[11n,7n],[2n,11n]];
var N,AREA,cells,t,NAMES;

var NS='http://www.w3.org/2000/svg';
// ---------- base-62 codec (RequestProject.UseSvg, BigInt) ----------
function decChar(c){var i=B62.indexOf(c);return i<0?0:i;}
function encChar(d){return B62.charAt(d);}
function decFixed(w,cs,pos){var v=0n,mul=1n;for(var i=0;i<w;i++){if(pos>=cs.length)return null;v+=BigInt(decChar(cs.charAt(pos)))*mul;mul*=62n;pos++;}return {v:v,pos:pos};}
function encFixed(w,n){var s='',m=n;for(var i=0;i<w;i++){s+=encChar(Number(m%62n));m=m/62n;}return s;}
function width62(n){var w=1,m=n;while(m>=62n){m=m/62n;w++;}return w;}
function decNat(cs,pos){var r=decFixed(2,cs,pos);if(!r)return null;var w=Number(r.v);var r2=decFixed(w,cs,r.pos);if(!r2)return null;return {v:r2.v,pos:r2.pos};}
function encNat(n){var w=width62(n);return encFixed(2,BigInt(w))+encFixed(w,n);}
function decNatsN(k,cs,pos){var out=[];for(var i=0;i<k;i++){var r=decNat(cs,pos);if(!r)return out;out.push(r.v);pos=r.pos;}return out;}
function encNats(a){var s='';for(var i=0;i<a.length;i++)s+=encNat(a[i]);return s;}
function unpackB62(s){var r=decNat(s,0);if(!r)return [];var count=Number(r.v);return decNatsN(count,s,r.pos);}
function packB62(a){return encNat(BigInt(a.length))+encNats(a);}
// ---------- recover a function's name from its number (MathlibSugar2.numGlyphA) ----------
function recoverName(n){var s='',m=n;while(m>0n){var d=Number(m%ABASE);s+=(d-1>=0&&d-1<ALPHA.length)?ALPHA.charAt(d-1):'?';m=m/ABASE;}return s;}
// ---------- Hilbert curve bijection (RequestProject.Hilbert) ----------
function rot(n,x,y,rx,ry){if(ry===0){if(rx===1){x=n-1-x;y=n-1-y;}return [y,x];}return [x,y];}
function d2xy(order,d){var x=0,y=0,s=1,tt=d;for(var k=0;k<order;k++){var rx=1&Math.floor(tt/2);var ry=1&(tt^rx);var p=rot(s,x,y,rx,ry);x=p[0];y=p[1];x+=s*rx;y+=s*ry;s*=2;tt=Math.floor(tt/4);}return [x,y];}
function xy2d(order,x,y){var nn=1<<order,d=0,s=nn>>1;for(var k=0;k<order;k++){var rx=(x&s)>0?1:0;var ry=(y&s)>0?1:0;d+=s*s*((3*rx)^ry);var p=rot(nn,x,y,rx,ry);x=p[0];y=p[1];s=s>>1;}return d;}
// ---------- FRACTRAN (RequestProject.Fractran) ----------
function fstep(prog,n){var b=BigInt(n);for(var i=0;i<prog.length;i++){var p=prog[i][0],q=prog[i][1];if(q!==0n&&(b*p)%q===0n)return Number((b*p)/q);}return n;}
function expo(p,n){var e=0;while(p>=2&&n!==0&&n%p===0){n=Math.floor(n/p);e++;}return e;}
// ---------- board on the Hilbert tape ----------
function get(x,y){return (x>=0&&x<N&&y>=0&&y<N)?cells[xy2d(ORDER,x,y)]:0;}
function snap(g){var a=new Array(N*N);for(var y=0;y<N;y++)for(var x=0;x<N;x++)a[x+y*N]=g(x,y);return a;}
function gg(a){return function(x,y){return (x>=0&&x<N&&y>=0&&y<N)?a[x+y*N]:0;};}
function nbrs(g,x,y){var c=0;for(var dy=-1;dy<=1;dy++)for(var dx=-1;dx<=1;dx++){if(dx===0&&dy===0)continue;if(g(x+dx,y+dy)!==0)c++;}return c;}
function birth(x,y){return Math.pow(2,1+x%3)*Math.pow(3,1+y%3);}
function spawnStage(g,x,y){var cur=g(x,y);if(cur!==0)return cur;if(t%5===0&&y<=1){var cx=(Math.floor(t/5)*5+2)%(N-2);if(cx<=x&&x<cx+2)return birth(x,t);return 0;}return 0;}
function gravStage(g,x,y){var cur=g(x,y);if(cur!==0&&y+1<N&&g(x,y+1)===0)return 0;if(cur===0&&y>=1&&g(x,y-1)!==0)return g(x,y-1);return cur;}
function lifeStage(g,x,y){var nb=nbrs(g,x,y),v=g(x,y);if(v!==0)return (nb>=1&&nb<=5)?v:0;return (nb===3)?birth(x,y):0;}
function mutStage(g,x,y){var v=g(x,y);if(v===0)return 0;v=fstep(PROG,v);if(nbrs(g,x,y)>=1)v=fstep(PROG,v);if(v>STATEBOUND)v=(v%STATEBOUND)+2;return v;}
function clearStage(g,x,y){for(var xx=0;xx<N;xx++){if(g(xx,y)===0)return g(x,y);}return 0;}
function tick(){
 var g0=get;
 var g1=gg(snap(function(x,y){return spawnStage(g0,x,y);}));
 var g2=gg(snap(function(x,y){return gravStage(g1,x,y);}));
 var g3=gg(snap(function(x,y){return lifeStage(g2,x,y);}));
 var g4=gg(snap(function(x,y){return mutStage(g3,x,y);}));
 var g5=gg(snap(function(x,y){return clearStage(g4,x,y);}));
 var nc=new Array(AREA);for(var i=0;i<AREA;i++){var q=d2xy(ORDER,i);nc[i]=g5(q[0],q[1]);}
 cells=nc;t++;
}
// ---------- colour + render ----------
function fill(v){var e=expo(2,v)+expo(3,v)+expo(5,v)+expo(7,v);var hue=(200+v*11)%360;var light=40+(e*9)%44;return 'hsl('+hue+',78%,'+light+'%)';}
function render(){
 var cg=document.getElementById('cells');while(cg.firstChild)cg.removeChild(cg.firstChild);
 var pop=0;
 for(var y=0;y<N;y++)for(var x=0;x<N;x++){var v=get(x,y);if(v===0)continue;pop++;
  var e=document.createElementNS(NS,'rect');var px=MARGIN+x*CELL,py=MARGIN+y*CELL,w=CELL-2;
  e.setAttribute('x',px+1);e.setAttribute('y',py+1);e.setAttribute('width',w);e.setAttribute('height',w);
  e.setAttribute('rx',2);e.setAttribute('ry',2);e.setAttribute('fill',fill(v));cg.appendChild(e);}
 var cap=document.getElementById('cap');
 if(cap)cap.textContent='recovered '+NAMES.length+' functions  |  t='+t+'  pop='+pop+'  |  e.g. '+(NAMES[0]||'')+', '+(NAMES[1]||'');
}
// ---------- self-serialisation: emit the next generation as a fresh SVG ----------
function currentNumbers(){var a=[];for(var i=0;i<AREA;i++)a.push(BigInt(cells[i]||0));while(a.length>0&&a[a.length-1]===0n)a.pop();return a;}
function snapshotSvg(){var pl=packB62(currentNumbers());var s=new XMLSerializer().serializeToString(document.documentElement);s=s.replace(/(<desc id="fx-data">)[^<]*(<\/desc>)/,'$1'+pl+'$2');return '<?xml version="1.0" encoding="UTF-8"?>\n'+s;}
function download(){try{var blob=new Blob([snapshotSvg()],{type:'image/svg+xml'});var url=URL.createObjectURL(blob);var a=document.createElementNS('http://www.w3.org/1999/xhtml','a');a.setAttribute('href',url);a.setAttribute('download','usesvg-next.svg');(document.body||document.documentElement).appendChild(a);a.click();}catch(e){}}
try{window.usesvgSnapshot=snapshotSvg;window.usesvgDownload=download;}catch(e){}
// ---------- boot: decode our own payload and run ----------
function init(){
 N=1<<ORDER;AREA=N*N;
 var data=document.getElementById('fx-data');
 var payload=data?(data.textContent||'').replace(/\s+/g,''):'';
 var nums=payload?unpackB62(payload):[];
 NAMES=nums.map(recoverName);
 cells=new Array(AREA);
 for(var i=0;i<AREA;i++){if(i<nums.length){var v=Number(nums[i]%BigInt(STATEBOUND));cells[i]=(v%4===0)?((v%5)+2):0;}else cells[i]=0;}
 t=0;render();setInterval(function(){tick();render();},FRAMEMS);
}
init();

//
